package com.bank.weak;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class WeakHashMapTest {

    @Test
    void weakHashMap_entryRemovedAfterGC() {
        WeakHashMap<Object, String> cache = new WeakHashMap<>();
        Object key = new Object();
        cache.put(key, "account-metadata");
        assertThat(cache).hasSize(1);

        key = null;       // remove strong reference!
        System.gc();      // request GC
        // GC may collect the weak key → entry removed

        // Note: GC is not guaranteed to run immediately,
        // but in practice this usually works in tests
    }

    @Test
    void hashMap_entryStaysForever() {
        HashMap<Object, String> cache = new HashMap<>();
        Object key = new Object();
        cache.put(key, "account-metadata");

        key = null;       // remove strong reference
        System.gc();

        assertThat(cache).hasSize(1);  // STILL 1! HashMap holds strong ref to key!
        // Memory leak if you forget to remove!
    }

    @Test
    void stringLiterals_neverCollected() {
        WeakHashMap<String, String> map = new WeakHashMap<>();
        map.put("SAV2001", "Rajesh");  // string literal → string pool → strong ref!
        System.gc();
        assertThat(map).hasSize(1);  // NOT collected! String pool holds it.
    }
}
