class MetadataCache {
    // key = weak reference; value stays until key GC'd
    private final Map<ClassLoader,ModuleMeta> cache =
            new WeakHashMap<>();

    ModuleMeta get(ClassLoader cl) {
        return cache.computeIfAbsent(cl, this::parseMeta);
    }
    // When 'cl' loses all strong refs (module hot-reloaded):
    //   1. GC reclaims the ClassLoader key
    //   2. WeakHashMap's ReferenceQueue drains stale entries
    //   3. entrySet() no longer shows it — no leak
    int liveModules() { return cache.size(); }  // shrinks after GC

    // GOTCHA: String literal keys are pool-strong → never evicted.
    // Use real object keys (ClassLoader) for weak semantics.
}
